/**
 * 43-06 — Partition Lifecycle Load Test
 *
 * P4 requirement: run the audit archive worker under 5 K inserts/min to
 * audit log, measure:
 *   ✓ Lock contention (shows as P99 write latency spikes)
 *   ✓ Partition detach time (measured via job history endpoint)
 *   ✓ Legal hold guard check overhead (trigger archive when hold is active;
 *     verify no partition is detached while hold covers it)
 *
 * ── How audit inserts are generated ──────────────────────────────────────────
 * k6 cannot write to Postgres directly.  Audit rows are generated by driving
 * record CRUD endpoints — each POST /records/:entity triggers writeRouteAudit()
 * which inserts one row into log.audit_log (partitioned by created_at).
 *
 * 5 K/min = ~83 inserts/s
 * 100 VUs × 0.5 req/s each = 50 req/s → use 170 VUs for headroom.
 *
 * ── Scenarios ────────────────────────────────────────────────────────────────
 *   audit_load         170 VUs × 5 m — drive record CRUDs → audit inserts
 *   archive_trigger      1 VU × 1 iter — POST to enqueue a partition-archive sweep
 *   legal_hold_guard     1 VU × 1 iter — assert hold-protected partition NOT archived
 *   monitor_archive      1 VU × 5 m — poll job history for archive job results
 *
 * ── Thresholds ───────────────────────────────────────────────────────────────
 *   audit_insert_ms      p(95) < 300  (write latency budget)
 *   audit_insert_ms      p(99) < 1000 (lock contention outlier ceiling)
 *   http_req_failed      rate  < 0.02
 *   legal_hold_violations count == 0  (zero tolerance)
 *
 * ── Prerequisites ────────────────────────────────────────────────────────────
 *   • Server running, partition-archive worker registered (Sprint 27)
 *   • log.audit_log partitioned by created_at (monthly partitions exist)
 *   • At least one audit_log partition older than PARTITION_RETENTION_MONTHS
 *     (default: 13 months) is detachable in test; otherwise archive sweep is a no-op
 *   • ADMIN_TOKEN env var — token with jobs admin access
 *   • BASE_URL, TOKEN_TENANT_A, ORG_TENANT_A set
 *
 * ── Run ──────────────────────────────────────────────────────────────────────
 *   k6 run \
 *     -e BASE_URL=http://localhost:3001/api \
 *     -e TOKEN_TENANT_A=eyJ... \
 *     -e ORG_TENANT_A=demo-org \
 *     -e ADMIN_TOKEN=eyJ... \
 *     perf/k6/43-06-partition-lifecycle.k6.js
 */

import http    from 'k6/http';
import { check, sleep } from 'k6';
import { Trend, Counter, Gauge, Rate } from 'k6/metrics';
import { ENV }      from './shared/env.js';
import { headersA } from './shared/headers.js';
import { safeParseJson } from './shared/utils.js';

// ── Custom metrics ────────────────────────────────────────────────────────────

/** Duration of each record-create call (proxy for audit insert latency) */
const auditInsertMs         = new Trend('audit_insert_ms', true);
/** Duration of last observed archive-partition job */
const archiveDetachMs       = new Trend('archive_detach_ms', true);
/** Running count of audit insert calls made */
const auditInsertCount      = new Counter('audit_insert_count');
/** Count of archive attempts on hold-protected partitions (must be 0) */
const legalHoldViolations   = new Counter('legal_hold_violations');
/** Last observed queue depth for jobs-partition-archive */
const archiveQueueWaiting   = new Gauge('archive_queue_waiting');
/** Rate of successful audit insert calls */
const auditInsertSuccessRate = new Rate('audit_insert_success_rate');

// ── Entity used for audit-load scenario ───────────────────────────────────────
// Must be a real entity in your seed data with a writable records endpoint.
const AUDIT_ENTITY = __ENV.AUDIT_ENTITY || 'product';

// ── k6 options ────────────────────────────────────────────────────────────────

export const options = {
  scenarios: {
    /**
     * Audit load: 170 VUs creating records to drive audit log inserts.
     * ~83 inserts/s target → 5 K inserts/min.
     * Each VU uses a ~0.6s think-time → ~1.67 req/s/VU × 50 VUs ≈ 83 req/s.
     * (Tune VU count if your DB can absorb more.)
     */
    audit_load: {
      executor:  'constant-vus',
      vus:       50,              // start conservative; raise to 170 if DB handles it
      duration:  '5m',
      tags:      { scenario: 'audit_load' },
      env:       { SCENARIO: 'audit_load' },
    },

    /**
     * Archive trigger: enqueue one partition-archive SWEEP job via admin API.
     * The sweep scans pg_inherits, checks legal holds, and dispatches
     * ARCHIVE_PARTITION jobs for eligible partitions.
     */
    archive_trigger: {
      executor:    'per-vu-iterations',
      vus:         1,
      iterations:  1,
      startTime:   '30s',         // allow some audit rows to accumulate first
      maxDuration: '60s',
      tags:        { scenario: 'archive_trigger' },
      env:         { SCENARIO: 'archive_trigger' },
    },

    /**
     * Legal hold guard: assert that a partition covered by an active hold was
     * NOT detached after the sweep ran.
     */
    legal_hold_guard: {
      executor:    'per-vu-iterations',
      vus:         1,
      iterations:  1,
      startTime:   '3m',          // after sweep should have completed
      maxDuration: '60s',
      tags:        { scenario: 'legal_hold_guard' },
      env:         { SCENARIO: 'legal_hold_guard' },
    },

    /**
     * Archive monitor: poll jobs history endpoint for ARCHIVE_PARTITION jobs
     * to measure actual detach duration + confirm legal hold was respected.
     */
    monitor_archive: {
      executor:  'constant-vus',
      vus:       1,
      duration:  '5m',
      startTime: '30s',
      tags:      { scenario: 'monitor_archive' },
      env:       { SCENARIO: 'monitor_archive' },
    },
  },

  thresholds: {
    // Audit write latency (end-to-end HTTP, includes auth + DB insert)
    'audit_insert_ms':          ['p(95)<300', 'p(99)<1000'],
    // Zero partition detachments when a legal hold is active
    'legal_hold_violations':    ['count==0'],
    // HTTP error budget
    'http_req_failed':          ['rate<0.02'],
    // > 95% audit inserts succeed
    'audit_insert_success_rate': ['rate>0.95'],
  },
};

// ── Setup: create a legal hold for the guard scenario ─────────────────────────

export function setup() {
  const adminHdrs = buildAdminHeaders();

  // Create an active legal hold covering the current month's audit partition.
  // The hold should block ANY archive attempt that overlaps this date range.
  const today     = new Date();
  const holdFrom  = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().slice(0, 10);
  const holdTo    = new Date(today.getFullYear(), today.getMonth() + 1, 0).toISOString().slice(0, 10);

  const holdBody = JSON.stringify({
    title:           'Perf test legal hold — 43-06',
    description:     'Created by k6 partition-lifecycle test. Remove after test.',
    scope_date_from: holdFrom,
    scope_date_to:   holdTo,
    // null scope_log_schemas = covers all log schemas
  });

  let holdId = null;
  const holdRes = http.post(
    `${ENV.BASE_URL}/audit/legal-holds`,
    holdBody,
    { headers: adminHdrs },
  );

  if (holdRes.status === 201 || holdRes.status === 200) {
    const body = safeParseJson(holdRes.body);
    holdId = body?.id ?? body?.data?.id;
    console.log(`[43-06 setup] Legal hold created: ${holdId} (${holdFrom} → ${holdTo})`);
  } else {
    console.warn(
      `[43-06 setup] Could not create legal hold (${holdRes.status}): ${holdRes.body}. ` +
      'Legal hold guard test will be skipped.',
    );
  }

  return { holdId, holdFrom, holdTo };
}

// ── Default function ──────────────────────────────────────────────────────────

export default function (data) {
  const scenario = __ENV.SCENARIO;

  if (scenario === 'audit_load')       runAuditLoad();
  else if (scenario === 'archive_trigger')  runArchiveTrigger(data);
  else if (scenario === 'legal_hold_guard') runLegalHoldGuard(data);
  else if (scenario === 'monitor_archive')  runMonitorArchive(data);
}

// ── Scenario implementations ──────────────────────────────────────────────────

function runAuditLoad() {
  const hdrs = headersA(ENV);

  // Each record create triggers writeRouteAudit → 1 row in log.audit_log
  const body = JSON.stringify({
    name:        `perf-audit-${__VU}-${__ITER}-${Date.now()}`,
    description: 'k6 partition lifecycle test record',
    status:      'active',
  });

  const res = http.post(
    `${ENV.BASE_URL}/records/${AUDIT_ENTITY}`,
    body,
    { headers: hdrs, tags: { name: 'audit_insert' } },
  );

  const ok = res.status === 200 || res.status === 201;
  auditInsertSuccessRate.add(ok ? 1 : 0);
  auditInsertMs.add(res.timings.duration);
  if (ok) auditInsertCount.add(1);

  check(res, {
    'record created (audit triggered)': (r) => r.status === 200 || r.status === 201,
    'insert latency < 300ms p95':       (r) => r.timings.duration < 1000, // per-request guard
  });

  // ~1.67 req/s per VU
  sleep(0.6);
}

function runArchiveTrigger(data) {
  const adminHdrs = buildAdminHeaders();

  // Trigger partition-archive SWEEP via the DLQ admin endpoint by enqueueing
  // a sweep job directly.  Uses GET /api/jobs/admin/history to verify it ran.
  //
  // If no admin trigger endpoint exists, the sweep runs on its monthly cron
  // schedule (1st of month at 02:00) — in that case this scenario just polls.
  console.log('[43-06 archive_trigger] Enqueueing partition-archive sweep job...');

  // First, attempt to enqueue via a POST to the jobs admin endpoint.
  // If this endpoint doesn't exist, log and skip — the monitor scenario
  // will still detect if a sweep runs via the cron schedule.
  const sweepBody = JSON.stringify({
    name:    'sweep',
    data:    {},
    opts:    { attempts: 1 },
  });

  const enqueueRes = http.post(
    `${ENV.BASE_URL}/jobs/admin/queues/partition-archive/add-job`,
    sweepBody,
    { headers: adminHdrs, tags: { name: 'enqueue_sweep' } },
  );

  if (enqueueRes.status === 200 || enqueueRes.status === 201) {
    console.log('[43-06 archive_trigger] Sweep job enqueued');
    check(enqueueRes, { 'sweep job enqueued': (r) => r.status === 200 || r.status === 201 });
  } else if (enqueueRes.status === 404 || enqueueRes.status === 405) {
    // Admin enqueue endpoint not implemented — acceptable, sweep runs on schedule
    console.log('[43-06 archive_trigger] Admin enqueue endpoint not available (404/405); '
      + 'partition sweep will run on cron schedule. Monitor scenario will detect results.');
  } else {
    console.warn(
      `[43-06 archive_trigger] Unexpected status ${enqueueRes.status}: ${enqueueRes.body}`,
    );
  }
}

function runLegalHoldGuard(data) {
  if (!data?.holdId) {
    console.warn('[43-06 hold_guard] No hold created in setup — skipping guard check');
    return;
  }

  const adminHdrs = buildAdminHeaders();

  // Inspect the legal hold's manifest.  If the manifest contains partition
  // entries with status='blocked' → the hold guard worked correctly.
  // If a partition was detached while covered → legal_hold_violations++.
  const manifestRes = http.get(
    `${ENV.BASE_URL}/audit/legal-holds/${data.holdId}`,
    { headers: adminHdrs, tags: { name: 'hold_manifest' } },
  );

  if (manifestRes.status !== 200) {
    console.warn(
      `[43-06 hold_guard] Could not retrieve hold manifest (${manifestRes.status})`,
    );
    return;
  }

  const body     = safeParseJson(manifestRes.body);
  const manifest = body?.manifest ?? body?.data?.manifest ?? [];

  // Each manifest entry must be blocked (not detached).
  // Track violations with a local counter so we can reference the value in check().
  let detachedCount = 0;
  for (const entry of manifest) {
    const isDetached = entry.status === 'detached' || entry.archived === true;
    if (isDetached) {
      detachedCount++;
      legalHoldViolations.add(1);
      console.error(
        `[43-06 hold_guard] VIOLATION: partition ${entry.partition_name} was detached ` +
        `despite active legal hold ${data.holdId}!`,
      );
    }
  }

  check(manifestRes, {
    'hold manifest returned':                  (r) => r.status === 200,
    'no hold-protected partitions detached':   () => detachedCount === 0,
  });

  if (manifest.length > 0) {
    console.log(
      `[43-06 hold_guard] Hold ${data.holdId}: ${manifest.length} manifest entries, ` +
      `violations=${detachedCount}`,
    );
  } else {
    console.log(
      `[43-06 hold_guard] No manifest entries yet — archive sweep may not have run, ` +
      'or no eligible partitions exist. This is not a failure.',
    );
  }
}

function runMonitorArchive(data) {
  const adminHdrs = buildAdminHeaders();

  // Poll job run history for recent partition-archive jobs
  const historyRes = http.get(
    `${ENV.BASE_URL}/jobs/admin/history?job_type=partition_archive&limit=20`,
    { headers: adminHdrs, tags: { name: 'archive_history' } },
  );

  if (historyRes.status === 200) {
    const body = safeParseJson(historyRes.body);
    const jobs = body?.items ?? body?.data ?? [];

    for (const job of jobs) {
      const durMs = Number(job.duration_ms ?? job.elapsed_ms ?? 0);
      if (durMs > 0) archiveDetachMs.add(durMs);
    }

    if (jobs.length > 0) {
      const maxDur = Math.max(...jobs.map((j) => Number(j.duration_ms ?? 0)));
      console.log(
        `[43-06 monitor] archive history: ${jobs.length} jobs, max detach time: ${maxDur}ms`,
      );
    }

    // Also poll partition-archive queue depth
    const queueRes = http.get(
      `${ENV.BASE_URL}/jobs/partition-archive`,
      { headers: adminHdrs, tags: { name: 'archive_queue_poll' } },
    );

    if (queueRes.status === 200) {
      const q      = safeParseJson(queueRes.body);
      const counts = q?.counts ?? {};
      archiveQueueWaiting.add(Number(counts.waiting ?? 0));
    }
  }

  sleep(10);
}

// ── Teardown: release the legal hold ─────────────────────────────────────────

export function teardown(data) {
  if (!data?.holdId) return;

  const adminHdrs = buildAdminHeaders();
  const releaseRes = http.patch(
    `${ENV.BASE_URL}/audit/legal-holds/${data.holdId}/release`,
    '{}',
    { headers: adminHdrs },
  );

  if (releaseRes.status === 200) {
    console.log(`[43-06 teardown] Legal hold ${data.holdId} released`);
  } else {
    console.warn(
      `[43-06 teardown] Could not release hold (${releaseRes.status}) — `+
      'remove it manually via: PATCH /audit/legal-holds/:id/release',
    );
  }
}

// ── Utilities ─────────────────────────────────────────────────────────────────

function buildAdminHeaders() {
  const adminToken = __ENV.ADMIN_TOKEN || '';
  const adminOrg   = __ENV.ADMIN_ORG   || ENV.ORG_A;
  const adminRealm = __ENV.ADMIN_REALM  || ENV.REALM_A;

  if (adminToken) {
    return {
      Authorization:  `Bearer ${adminToken}`,
      'X-Org':        adminOrg,
      'X-Realm':      adminRealm,
      'Content-Type': 'application/json',
    };
  }
  return headersA(ENV);
}

